import numpy as np
def load(fn):
    lines=open(fn).read().splitlines(); n=int(lines[0])
    els=[];xyz=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
    return els, np.array(xyz)
els,xyz = load('opt1.xyz')
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
def ang(i,j,k):
    a=xyz[i]-xyz[j]; b=xyz[k]-xyz[j]
    return np.degrees(np.arccos(a@b/np.linalg.norm(a)/np.linalg.norm(b)))
print("Ru-N6 %.2f Ru-C14 %.2f Ru-C28 %.2f Ru-H %.2f Ru-C2 %.2f Ru-C4 %.2f"%(d(0,6),d(0,14),d(0,28),d(0,1),d(0,2),d(0,4)))
print("angles N6-Ru-C14 %.1f N6-Ru-C28 %.1f C14-Ru-C28 %.1f H-Ru-C2 %.1f H-Ru-C4 %.1f C2-Ru-C4 %.1f"%(ang(6,0,14),ang(6,0,28),ang(14,0,28),ang(1,0,2),ang(1,0,4),ang(2,0,4)))
print("N13-C11 %.2f N27-C12 %.2f C12-C7 %.2f"%(d(13,11),d(27,12),d(12,7)))
print("C-O %.2f %.2f"%(d(2,3),d(4,5)))
# check min nonbonded
import itertools
mind=9; pair=None
for i,j in itertools.combinations(range(len(els)),2):
    dd=d(i,j)
    if dd<mind: mind=dd; pair=(i,els[i],j,els[j])
print("min dist %.2f"%mind, pair)
